window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fa40575daaf0f31e"]={"versions": [{"id": "FIG-fa40575daaf0f31e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (Spezifikation des Manifests, TPS Manifest Specification). Das Diagramm modelliert die Obergrenzen und Begrenzungen des Ressourcenverbrauchs (<code>ResourceConsumption</code>) für einen bestimmten Prozess im Kontext von zustandsabhängigen Startkonfigurationen (<code>StateDependentStartupConfig</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>StateDependentStartupConfig</code>: Übergeordnete Konfigurationsklasse; besitzt per Komposition eine optionale Rolle <code>+resourceConsumption</code> mit Multiplizität <code>0..1</code> zur Klasse <code>ResourceConsumption</code>.</li>\n<li><code>ResourceConsumption</code>: Spezialisiert <code>Identifiable</code>. Aggregiert über Kompositionen zwei Arten von Speichernutzungen:</li>\n<li><code>+systemMemoryUsage</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpSplitable»</code>): Verweist auf <code>SystemMemoryUsage</code>.</li>\n<li><code>+heapUsage</code> (Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation,atpSplitable»</code>): Verweist auf <code>HeapUsage</code>.</li>\n<li><code>SystemMemoryUsage</code>: Spezialisiert <code>Identifiable</code>. Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger</code>.</li>\n<li><code>HeapUsage</code>: Spezialisiert <code>Identifiable</code>. Dient als Basisklasse für spezifische Heap-Verbrauchsbeschreibungen; enthält keine eigenen Attribute.</li>\n<li><code>WorstCaseHeapUsage</code>: Spezialisiert <code>HeapUsage</code> per Generalisierung (Vererbungspfeil). Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger</code>.</li>\n<li>Notiz/Stereotyp-Spezifikation: An der Assoziation <code>+heapUsage</code> ist per gestrichelter Linie ein Kommentar annotiert mit <code>«atpVariation» Tags: vh.latestBindingTime = preCompileTime</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar. Zur Laufzeit bzw. Konfigurationszeit bestimmt eine Instanz von <code>StateDependentStartupConfig</code> für einen Prozess die zulässigen Grenzwerte des Ressourcenverbrauchs. Über <code>ResourceConsumption</code> können für verschiedene Systemzustände Grenzwerte für den Gesamtspeicher (<code>SystemMemoryUsage</code>) sowie für den Worst-Case-Heap-Verbrauch (<code>WorstCaseHeapUsage</code> als Spezialisierung von <code>HeapUsage</code>) spezifiziert werden. Die Variationspunktbindung für den Heap-Verbrauch ist auf <code>preCompileTime</code> festgelegt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute <code>memoryConsumption</code> in <code>SystemMemoryUsage</code> und <code>WorstCaseHeapUsage</code> sind als <code>PositiveInteger</code> typisiert und definieren verbindliche Speicherobergrenzen (in der Regel in Bytes). Das Stereotyp <code>«atpSplitable»</code> an beiden Kompositionen erlaubt die Verteilung der Modellelemente über mehrere ARXML-Dateien. Die Kennzeichnung <code>«atpVariation»</code> mit Bindungszeit <code>preCompileTime</code> an <code>+heapUsage</code> erzwingt, dass Variationen der Heap-Grenzen spätestens zum Vorkompilierungszeitpunkt aufgelöst sein müssen.</p>"}, {"id": "FIG-f446c9da9297d441", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (Spezifikation des Manifests, TPS Manifest Specification). Das Diagramm modelliert die Obergrenzen und Begrenzungen des Ressourcenverbrauchs (<code>ResourceConsumption</code>) für einen bestimmten Prozess im Kontext von zustandsabhängigen Startkonfigurationen (<code>StateDependentStartupConfig</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>StateDependentStartupConfig</code>: Übergeordnete Konfigurationsklasse; besitzt per Komposition eine optionale Rolle <code>+resourceConsumption</code> mit Multiplizität <code>0..1</code> zur Klasse <code>ResourceConsumption</code>.</li>\n<li><code>ResourceConsumption</code>: Spezialisiert <code>Identifiable</code>. Aggregiert über Kompositionen zwei Arten von Speichernutzungen:</li>\n<li><code>+systemMemoryUsage</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpSplitable»</code>): Verweist auf <code>SystemMemoryUsage</code>.</li>\n<li><code>+heapUsage</code> (Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation,atpSplitable»</code>): Verweist auf <code>HeapUsage</code>.</li>\n<li><code>SystemMemoryUsage</code>: Spezialisiert <code>Identifiable</code>. Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger</code>.</li>\n<li><code>HeapUsage</code>: Spezialisiert <code>Identifiable</code>. Dient als Basisklasse für spezifische Heap-Verbrauchsbeschreibungen; enthält keine eigenen Attribute.</li>\n<li><code>WorstCaseHeapUsage</code>: Spezialisiert <code>HeapUsage</code> per Generalisierung (Vererbungspfeil). Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger</code>.</li>\n<li>Notiz/Stereotyp-Spezifikation: An der Assoziation <code>+heapUsage</code> ist per gestrichelter Linie ein Kommentar annotiert mit <code>«atpVariation» Tags: vh.latestBindingTime = preCompileTime</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar. Zur Laufzeit bzw. Konfigurationszeit bestimmt eine Instanz von <code>StateDependentStartupConfig</code> für einen Prozess die zulässigen Grenzwerte des Ressourcenverbrauchs. Über <code>ResourceConsumption</code> können für verschiedene Systemzustände Grenzwerte für den Gesamtspeicher (<code>SystemMemoryUsage</code>) sowie für den Worst-Case-Heap-Verbrauch (<code>WorstCaseHeapUsage</code> als Spezialisierung von <code>HeapUsage</code>) spezifiziert werden. Die Variationspunktbindung für den Heap-Verbrauch ist auf <code>preCompileTime</code> festgelegt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute <code>memoryConsumption</code> in <code>SystemMemoryUsage</code> und <code>WorstCaseHeapUsage</code> sind als <code>PositiveInteger</code> typisiert und definieren verbindliche Speicherobergrenzen (in der Regel in Bytes). Das Stereotyp <code>«atpSplitable»</code> an beiden Kompositionen erlaubt die Verteilung der Modellelemente über mehrere ARXML-Dateien. Die Kennzeichnung <code>«atpVariation»</code> mit Bindungszeit <code>preCompileTime</code> an <code>+heapUsage</code> erzwingt, dass Variationen der Heap-Grenzen spätestens zum Vorkompilierungszeitpunkt aufgelöst sein müssen.</p>"}, {"id": "FIG-4a3a47bc34e398a7", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (Spezifikation des Manifests, TPS Manifest Specification). Das Diagramm modelliert die Obergrenzen und Begrenzungen des Ressourcenverbrauchs (<code>ResourceConsumption</code>) für einen bestimmten Prozess im Kontext von zustandsabhängigen Startkonfigurationen (<code>StateDependentStartupConfig</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>StateDependentStartupConfig</code>: Übergeordnete Konfigurationsklasse; besitzt per Komposition eine optionale Rolle <code>+resourceConsumption</code> mit Multiplizität <code>0..1</code> zur Klasse <code>ResourceConsumption</code>.</li>\n<li><code>ResourceConsumption</code>: Spezialisiert <code>Identifiable</code>. Aggregiert über Kompositionen zwei Arten von Speichernutzungen:</li>\n<li><code>+systemMemoryUsage</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpSplitable»</code>): Verweist auf <code>SystemMemoryUsage</code>.</li>\n<li><code>+heapUsage</code> (Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation,atpSplitable»</code>): Verweist auf <code>HeapUsage</code>.</li>\n<li><code>SystemMemoryUsage</code>: Spezialisiert <code>Identifiable</code>. Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger</code>.</li>\n<li><code>HeapUsage</code>: Spezialisiert <code>Identifiable</code>. Dient als Basisklasse für spezifische Heap-Verbrauchsbeschreibungen; enthält keine eigenen Attribute.</li>\n<li><code>WorstCaseHeapUsage</code>: Spezialisiert <code>HeapUsage</code> per Generalisierung (Vererbungspfeil). Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger</code>.</li>\n<li>Notiz/Stereotyp-Spezifikation: An der Assoziation <code>+heapUsage</code> ist per gestrichelter Linie ein Kommentar annotiert mit <code>«atpVariation» Tags: vh.latestBindingTime = preCompileTime</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar. Zur Laufzeit bzw. Konfigurationszeit bestimmt eine Instanz von <code>StateDependentStartupConfig</code> für einen Prozess die zulässigen Grenzwerte des Ressourcenverbrauchs. Über <code>ResourceConsumption</code> können für verschiedene Systemzustände Grenzwerte für den Gesamtspeicher (<code>SystemMemoryUsage</code>) sowie für den Worst-Case-Heap-Verbrauch (<code>WorstCaseHeapUsage</code> als Spezialisierung von <code>HeapUsage</code>) spezifiziert werden. Die Variationspunktbindung für den Heap-Verbrauch ist auf <code>preCompileTime</code> festgelegt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute <code>memoryConsumption</code> in <code>SystemMemoryUsage</code> und <code>WorstCaseHeapUsage</code> sind als <code>PositiveInteger</code> typisiert und definieren verbindliche Speicherobergrenzen (in der Regel in Bytes). Das Stereotyp <code>«atpSplitable»</code> an beiden Kompositionen erlaubt die Verteilung der Modellelemente über mehrere ARXML-Dateien. Die Kennzeichnung <code>«atpVariation»</code> mit Bindungszeit <code>preCompileTime</code> an <code>+heapUsage</code> erzwingt, dass Variationen der Heap-Grenzen spätestens zum Vorkompilierungszeitpunkt aufgelöst sein müssen.</p>"}, {"id": "FIG-0a839cea2c3b1b4b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm modelliert die Abbildung des Speicherbedarfs (<code>MemoryUsage</code>) innerhalb des Ressourcenverbrauchs (<code>ResourceConsumption</code>) für eine gegebene zustandsabhängige Startkonfiguration (<code>StateDependentStartupConfig</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>StateDependentStartupConfig</code>: Übergeordnete Konfiguration; enthält per Komposition die Rolle <code>+resourceConsumption</code> mit Kardinalität <code>0..1</code> zur Klasse <code>ResourceConsumption</code>.</li>\n<li><code>ResourceConsumption</code>: Spezialisiert <code>Identifiable</code>. Hält über eine Komposition mit Rolle <code>+memoryUsage</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpSplitable»</code>) Instanzen der Klasse <code>MemoryUsage</code>.</li>\n<li><code>MemoryUsage</code>: Spezialisiert <code>Identifiable</code>. Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein statische Metamodell-Struktur. Für einen Prozess werden über <code>StateDependentStartupConfig</code> und <code>ResourceConsumption</code> null oder mehrere <code>MemoryUsage</code>-Objekte zugeordnet. Jedes <code>MemoryUsage</code>-Objekt kann optional über <code>memoryConsumption</code> einen konkreten Verbrauchswert als positive Ganzzahl definieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>memoryConsumption</code> ist als optionales Attribut (<code>[0..1]</code>) vom Typ <code>PositiveInteger</code> definiert. Das Stereotyp <code>«atpSplitable»</code> an der Komposition <code>+memoryUsage</code> gestattet die Zerlegung und Verteilung der Speichernutzungselemente über mehrere ARXML-Teildateien (Splitable). Spezifische Differenzierungen zwischen Heap und Systemspeicher sowie Variationspunkt-Stereotypen sind auf dieser Abstraktionsstufe nicht vorhanden.</p>"}, {"id": "FIG-a43fa09c798ea832", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm modelliert die Abbildung des Speicherbedarfs (<code>MemoryUsage</code>) innerhalb des Ressourcenverbrauchs (<code>ResourceConsumption</code>) für eine gegebene zustandsabhängige Startkonfiguration (<code>StateDependentStartupConfig</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>StateDependentStartupConfig</code>: Übergeordnete Konfiguration; enthält per Komposition die Rolle <code>+resourceConsumption</code> mit Kardinalität <code>0..1</code> zur Klasse <code>ResourceConsumption</code>.</li>\n<li><code>ResourceConsumption</code>: Spezialisiert <code>Identifiable</code>. Hält über eine Komposition mit Rolle <code>+memoryUsage</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpSplitable»</code>) Instanzen der Klasse <code>MemoryUsage</code>.</li>\n<li><code>MemoryUsage</code>: Spezialisiert <code>Identifiable</code>. Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein statische Metamodell-Struktur. Für einen Prozess werden über <code>StateDependentStartupConfig</code> und <code>ResourceConsumption</code> null oder mehrere <code>MemoryUsage</code>-Objekte zugeordnet. Jedes <code>MemoryUsage</code>-Objekt kann optional über <code>memoryConsumption</code> einen konkreten Verbrauchswert als positive Ganzzahl definieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>memoryConsumption</code> ist als optionales Attribut (<code>[0..1]</code>) vom Typ <code>PositiveInteger</code> definiert. Das Stereotyp <code>«atpSplitable»</code> an der Komposition <code>+memoryUsage</code> gestattet die Zerlegung und Verteilung der Speichernutzungselemente über mehrere ARXML-Teildateien (Splitable). Spezifische Differenzierungen zwischen Heap und Systemspeicher sowie Variationspunkt-Stereotypen sind auf dieser Abstraktionsstufe nicht vorhanden.</p>"}, {"id": "FIG-16721239d32dca0c", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm modelliert die Abbildung des Speicherbedarfs (<code>MemoryUsage</code>) innerhalb des Ressourcenverbrauchs (<code>ResourceConsumption</code>) für eine gegebene zustandsabhängige Startkonfiguration (<code>StateDependentStartupConfig</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>StateDependentStartupConfig</code>: Übergeordnete Konfiguration; enthält per Komposition die Rolle <code>+resourceConsumption</code> mit Kardinalität <code>0..1</code> zur Klasse <code>ResourceConsumption</code>.</li>\n<li><code>ResourceConsumption</code>: Spezialisiert <code>Identifiable</code>. Hält über eine Komposition mit Rolle <code>+memoryUsage</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpSplitable»</code>) Instanzen der Klasse <code>MemoryUsage</code>.</li>\n<li><code>MemoryUsage</code>: Spezialisiert <code>Identifiable</code>. Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein statische Metamodell-Struktur. Für einen Prozess werden über <code>StateDependentStartupConfig</code> und <code>ResourceConsumption</code> null oder mehrere <code>MemoryUsage</code>-Objekte zugeordnet. Jedes <code>MemoryUsage</code>-Objekt kann optional über <code>memoryConsumption</code> einen konkreten Verbrauchswert als positive Ganzzahl definieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>memoryConsumption</code> ist als optionales Attribut (<code>[0..1]</code>) vom Typ <code>PositiveInteger</code> definiert. Das Stereotyp <code>«atpSplitable»</code> an der Komposition <code>+memoryUsage</code> gestattet die Zerlegung und Verteilung der Speichernutzungselemente über mehrere ARXML-Teildateien (Splitable). Spezifische Differenzierungen zwischen Heap und Systemspeicher sowie Variationspunkt-Stereotypen sind auf dieser Abstraktionsstufe nicht vorhanden.</p>"}, {"id": "FIG-29c28df59f1320e9", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm modelliert die Abbildung des Speicherbedarfs (<code>MemoryUsage</code>) innerhalb des Ressourcenverbrauchs (<code>ResourceConsumption</code>) für eine gegebene zustandsabhängige Startkonfiguration (<code>StateDependentStartupConfig</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>StateDependentStartupConfig</code>: Übergeordnete Konfiguration; enthält per Komposition die Rolle <code>+resourceConsumption</code> mit Kardinalität <code>0..1</code> zur Klasse <code>ResourceConsumption</code>.</li>\n<li><code>ResourceConsumption</code>: Spezialisiert <code>Identifiable</code>. Hält über eine Komposition mit Rolle <code>+memoryUsage</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpSplitable»</code>) Instanzen der Klasse <code>MemoryUsage</code>.</li>\n<li><code>MemoryUsage</code>: Spezialisiert <code>Identifiable</code>. Besitzt das Attribut <code>+ memoryConsumption: PositiveInteger [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein statische Metamodell-Struktur. Für einen Prozess werden über <code>StateDependentStartupConfig</code> und <code>ResourceConsumption</code> null oder mehrere <code>MemoryUsage</code>-Objekte zugeordnet. Jedes <code>MemoryUsage</code>-Objekt kann optional über <code>memoryConsumption</code> einen konkreten Verbrauchswert als positive Ganzzahl definieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>memoryConsumption</code> ist als optionales Attribut (<code>[0..1]</code>) vom Typ <code>PositiveInteger</code> definiert. Das Stereotyp <code>«atpSplitable»</code> an der Komposition <code>+memoryUsage</code> gestattet die Zerlegung und Verteilung der Speichernutzungselemente über mehrere ARXML-Teildateien (Splitable). Spezifische Differenzierungen zwischen Heap und Systemspeicher sowie Variationspunkt-Stereotypen sind auf dieser Abstraktionsstufe nicht vorhanden.</p>"}], "trans": [{"from": "FIG-fa40575daaf0f31e", "to": "FIG-f446c9da9297d441", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f446c9da9297d441", "to": "FIG-4a3a47bc34e398a7", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Layout des Diagramms geändert: <code>StateDependentStartupConfig</code> von oberhalb <code>ResourceConsumption</code> nach rechts oben verschoben; die Komposition <code>+resourceConsumption</code> verläuft nun horizontal statt vertikal.</li>\n<li>Multiplizitätsangabe <code>0..1</code> an der Assoziation <code>+resourceConsumption</code> unterhalb des Rollennamens statt daneben platziert.</li>\n</ul>"}, {"from": "FIG-4a3a47bc34e398a7", "to": "FIG-0a839cea2c3b1b4b", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klassen <code>SystemMemoryUsage</code>, <code>HeapUsage</code> und <code>WorstCaseHeapUsage</code> entfernt.</li>\n<li>Neue Klasse <code>MemoryUsage</code> (spezialisiert <code>Identifiable</code>) eingeführt mit Attribut <code>+ memoryConsumption: PositiveInteger [0..1]</code>.</li>\n<li>Kompositionsziel von <code>ResourceConsumption</code> von <code>+systemMemoryUsage 0..<em></code> und <code>+heapUsage 0..</em></code> auf <code>+memoryUsage 0..*</code> geändert (Stereotyp <code>«atpSplitable»</code>).</li>\n<li>Stereotyp <code>«atpVariation»</code> und Notiz <code>«atpVariation» Tags: vh.latestBindingTime = preCompileTime</code> am Aggregat entfernt.</li>\n<li>Anordnung von <code>StateDependentStartupConfig</code> nach links vor <code>ResourceConsumption</code> verlagert.</li>\n</ul>"}, {"from": "FIG-0a839cea2c3b1b4b", "to": "FIG-a43fa09c798ea832", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a43fa09c798ea832", "to": "FIG-16721239d32dca0c", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-16721239d32dca0c", "to": "FIG-29c28df59f1320e9", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
